def equation(gate_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Equação empírica para log10(|ID|/A) ao longo da curva de transferência."""
    """Improved version of `equation_v1`
       taking into consideration a more complex relationship between the variables."""
    a, b, c, d = parameters
    return a + (b*gate_voltage_abs) + (c*np.exp(d*gate_voltage_abs))
